-- dsh-aegisub-bridge: in-memory subtitle bridge (macro WHALE_BRIDGE)
-- Generated by the DSH plugin. Re-run aegisub_setup after changing the template.
local DIR = "__WHALE_DIR__"

local function read_file(p)
  local f = io.open(p, "rb")
  if not f then return nil end
  local d = f:read("*a")
  f:close()
  return d
end

local function write_file(p, d)
  local f = io.open(p, "wb")
  if not f then return false end
  f:write(d)
  f:close()
  return true
end

local function esc(s)
  s = tostring(s)
  s = s:gsub("\\", "\\\\")
  s = s:gsub('"', '\\"')
  s = s:gsub("\r", "\\r")
  s = s:gsub("\n", "\\n")
  s = s:gsub("\t", "\\t")
  return s
end

local function num(v) if type(v) == "number" then return v end return 0 end
local function str(v) if v == nil then return "" end return tostring(v) end

local function dump_subs(subs, sel, active)
  local out = {}
  for i = 1, #subs do
    local l = subs[i]
    if l.class == "dialogue" then
      out[#out+1] = string.format(
        '{"i":%d,"layer":%d,"start":%d,"end":%d,"style":"%s","actor":"%s","ml":%d,"mr":%d,"mv":%d,"effect":"%s","comment":%s,"text":"%s"}',
        i, num(l.layer), num(l.start_time), num(l.end_time),
        esc(str(l.style)), esc(str(l.actor)),
        num(l.margin_l), num(l.margin_r), num(l.margin_v),
        esc(str(l.effect)), tostring(l.comment == true), esc(str(l.text)))
    end
  end
  return '{"count":' .. #out .. ',"total":' .. #subs .. ',"sel":[' .. table.concat(sel, ",") .. '],"active":' .. tostring(active) .. ',"lines":[' .. table.concat(out, ",") .. ']}'
end

local function apply_ops(subs)
  local cmd = read_file(DIR .. "command.lua")
  if not cmd then return 0, "no_command" end
  local chunk, perr = loadstring("return " .. cmd)
  if not chunk then return 0, "parse_fail:" .. tostring(perr) end
  local ok, data = pcall(chunk)
  if not ok or type(data) ~= "table" then return 0, "exec_fail" end
  local n = 0
  for _, op in ipairs(data.ops or {}) do
    if op.op == "set_text" and op.index then
      local l = subs[op.index]
      if l and l.class == "dialogue" then
        l.text = op.text
        subs[op.index] = l
        n = n + 1
      end
    elseif op.op == "set_style" and op.index and op.style then
      local l = subs[op.index]
      if l and l.class == "dialogue" then
        l.style = op.style
        subs[op.index] = l
        n = n + 1
      end
    elseif op.op == "replace" and op.find then
      for i = 1, #subs do
        local l = subs[i]
        if l.class == "dialogue" then
          local s, e = l.text:find(op.find, 1, true)
          if s then
            l.text = l.text:sub(1, s - 1) .. (op.repl or "") .. l.text:sub(e + 1)
            subs[i] = l
            n = n + 1
          end
        end
      end
    end
  end
  return n, "ok"
end

local function bridge(subs, sel, active)
  local ok, err = pcall(function()
    aegisub.progress.task("whale bridge: apply")
    local n, e2 = apply_ops(subs)
    if n > 0 then
      aegisub.set_undo_point("whale bridge")
    end
    aegisub.progress.task("whale bridge: dump")
    write_file(DIR .. "dump.json", dump_subs(subs, sel, active))
    write_file(DIR .. "result.json", string.format('{"ok":true,"applied":%d,"err":"%s","count":%d}', n, esc(e2), #subs))
  end)
  if not ok then
    write_file(DIR .. "error.txt", tostring(err))
  end
end

aegisub.register_macro("WHALE_BRIDGE", "whale bridge: apply then dump", bridge)
